// Static shell only. Business records and pending commands remain in IndexedDB and independent JSON backups.
const CACHE='mora-shell-d3c421c1d4f6dec6236d';
const ASSETS=['./mora-screens.css','./device-dialogs.js','./vendor/qrcode-generator.js','./ui-format.js','./experience-feedback.js','./command-domain.js','./auth-client.js','./remote-client.js','./workspace-store.js','./runtime-config.js','./persistence-controller.js','./','./index.html','./manifest.webmanifest','./assets/icons/mora-180.png','./assets/icons/mora-192.png','./assets/icons/mora-512.png','./assets/brand/mora-vineria.svg','./assets/brand/mora-vineria-light.svg','./assets/icons/mora-maskable-512.png','./assets/icons/mora-favicon.svg','./assets/icons/mora-favicon-32.png','./assets/brand/mora-wordmark.svg','./style.css','./areas.css','./refinement.css','./workflows.css','./writer-gate.js','./backup-summary.js','./app.js','./display-dates.js','./reports-model.js','./reports-ui.js','./money-history-ui.js','./correction-ui.js','./correction-validation.js','./sale-corrections.js','./workflow-ui.js','./workflow-state.js','./business-read.js','./extended-operations.js','./extended-validation.js','./shortage-model.js','./cart-model.js','./draft-model.js','./operations.js','./operation-validation.js','./product-model.js','./purchasing.js','./catalog-data.js','./scanner.js','./money-model.js','./local-data.js','./receiving.js','./purchase-orders.js','./supplier-engine.js','./costs.js','./update-gate.js','./assets/wine-red.webp','./assets/wine-white.webp','./assets/wine-rose.webp','./assets/accounts/brubank.png','./assets/accounts/mercado-pago.svg','./assets/accounts/naranja-x.webp'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS))));
// A new version activates once all tabs of the previous version are closed.
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE')self.skipWaiting();});
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('mora-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const r=event.request,url=new URL(r.url);if(r.method!=='GET'||url.origin!==self.location.origin||r.cache==='no-store')return;
  const allowed=ASSETS.some(a=>new URL(a,self.registration.scope).href===url.href);if(!allowed&&r.mode!=='navigate')return;
  event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(r))||(r.mode==='navigate'?await cache.match('./index.html'):null)||fetch(r)));
});
